// src/billing/notify.ts
interface Invoice { id: string; dueDate: string | Date; status: 'open' | 'paid'; }
interface Mailer { send(invoice: Invoice): Promise<{ id: string }>; }

export async function notifyOverdue(invoices: Invoice[], mailer: Mailer) {
  const now = Date.now();
  const THIRTY_DAYS_MS = 30 * 24 * 60 * 60 * 1000;
  const overdue = invoices.filter(
    (inv) => inv.status !== 'paid' && now - new Date(inv.dueDate).getTime() > THIRTY_DAYS_MS
  );
  const results = await Promise.all(overdue.map((inv) => mailer.send(inv)));
  return results;
}
```

